#include <bits/stdc++.h>
using namespace std;

class FastScanner {
private:
    static const int BUFSIZE = 1 << 20;
    char buf[BUFSIZE];
    int idx, size;
    inline char getChar() {
        if (idx >= size) {
            size = fread(buf, 1, BUFSIZE, stdin);
            idx = 0;
            if (size == 0) return EOF;
        }
        return buf[idx++];
    }
public:
    FastScanner() : idx(0), size(0) {}
    inline bool skip() {
        char c;
        do {
            c = getChar();
            if (c == EOF) return false;
        } while (c <= ' ');
        idx--;
        return true;
    }
    template<typename T>
    bool nextInt(T &out) {
        if (!skip()) return false;
        char c = getChar();
        bool neg = false;
        if (c == '-') {
            neg = true;
            c = getChar();
        }
        T val = 0;
        while (c > ' ') {
            val = val * 10 + (c - '0');
            c = getChar();
        }
        out = neg ? -val : val;
        return true;
    }
    int nextInt() {
        int x; nextInt(x); return x;
    }
    long long nextLong() {
        long long x; nextInt(x); return x;
    }
};

class FastWriter {
private:
    static const int BUFSIZE = 1 << 20;
    char buf[BUFSIZE];
    int idx;
public:
    FastWriter() : idx(0) {}
    ~FastWriter() { flush(); }
    inline void pushChar(char c) {
        if (idx >= BUFSIZE) flush();
        buf[idx++] = c;
    }
    inline void writeInt(long long x, char after) {
        if (x == 0) {
            pushChar('0');
            if (after) pushChar(after);
            return;
        }
        if (x < 0) {
            pushChar('-');
            x = -x;
        }
        char s[24];
        int n = 0;
        while (x > 0) {
            s[n++] = '0' + (x % 10);
            x /= 10;
        }
        for (int i = n - 1; i >= 0; --i) pushChar(s[i]);
        if (after) pushChar(after);
    }
    inline void writeString(const string &s) {
        for (char c : s) pushChar(c);
    }
    void flush() {
        if (idx > 0) {
            fwrite(buf, 1, idx, stdout);
            idx = 0;
        }
    }
} out;

int n, m;
vector<int> arr;
int required;
unordered_map<int, set<int>> typeDays;

bool isEnough(int day) {
    long long totalCoin = day;
    int req = required;

    vector<int> ddays(day + 1, 0);
    for (auto &p : typeDays) {
        int typ = p.first;
        const set<int> &daysSet = p.second;
        auto it = daysSet.upper_bound(day);
        if (it == daysSet.begin()) continue;
        --it;
        int lastDay = *it;
        ddays[lastDay] += arr[typ - 1];
    }

    int removed = 0;
    for (int i = 1; i <= day; i++) {
        int coins = i - removed;
        int toRemove = min(coins, ddays[i]);
        removed += toRemove;
        totalCoin -= toRemove;
        req -= toRemove;
    }
    return (long long)req * 2 <= totalCoin;
}

void solver() {
    FastScanner in;
    in.nextInt(n);
    in.nextInt(m);
    arr.resize(n);
    required = 0;
    for (int i = 0; i < n; i++) {
        in.nextInt(arr[i]);
        required += arr[i];
    }
    typeDays.clear();
    typeDays.reserve(m * 2);

    for (int i = 0; i < m; i++) {
        int d = in.nextInt();
        int typ = in.nextInt();
        if (arr[typ - 1] <= 0) continue;
        typeDays[typ].insert(d);
    }

    int lo = required;
    int hi = 2 * required;
    int valid = hi;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (isEnough(mid)) {
            valid = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    out.writeInt(valid, '\n');
}

int main() {
    solver();
    out.flush();
    return 0;
}

